@Test
    public void verifyBackFailureZeroIndex_oe_101_oe() throws IOException {
        try {
            final JSONTokener tokener = new JSONTokener(reader);
            try {
                // this should fail since the index is 0;
                tokener.back();
                fail("Expected an exception");
            } catch (JSONException e) {
            } catch (Exception e) {
            }

        } finally {
            reader.close();
        }
    }

@Test
    public void verifyBackFailureDoubleBack_oe_101_oe() throws IOException {
        try {
            final JSONTokener tokener = new JSONTokener(reader);
            tokener.next();
            tokener.back();
            try {
                // this should fail since the index is 0;
                tokener.back();
                fail("Expected an exception");
            } catch (JSONException e) {
            } catch (Exception e) {
            }
       } finally {
           reader.close();
       }
    }

@Test
    public void testSkipToFailureWithBufferedReader_oe_101_oe() throws IOException {
        try {
            final JSONTokener tokener = new JSONTokener(reader);
            try {
                // this should fail since the internal markAhead buffer is only 1,000,000
                // but 'B' doesn't exist in our buffer that is 1,000,001 in size
                tokener.skipTo('B');
                fail("Expected exception");
            } catch (JSONException e) {
            } catch (Exception e) {
            }
        } finally {
            reader.close();
        }
    }

